//! What runui-tea renders, compared with what the Go libraries render for the
//! same scenarios: `golden_data.rs` holds Go's output (Lip Gloss, x/ansi,
//! Bubbles, Bubble Tea), generated by a Go program that sets up each
//! scenario as below.

mod golden_data;

