const LONG: &str = "AEM builds a temporary package with the same filter (3 roots), aem-cli downloads it and deletes it again. Content on AEM doesn't change.";

struct Out(Vec<(String, String)>);

impl Out {
    fn add(&mut self, name: impl Into<String>, value: impl Into<String>) {
        self.0.push((name.into(), value.into()));
    }
}

