fn ansi_fns(o: &mut Out) {
    let s = S_TITLE.render("Packages") + " " + &S_DIM.render("On this Mac · 12 of 40") + " 你好🫧";
    for w in [0, 1, 5, 9, 10, 20, 30, 33, 34, 40] {
        o.add(format!("truncate_{w}"), ansi::truncate(&s, w, "…"));
        o.add(format!("truncate_left_{w}"), ansi::truncate_left(&s, w, "…"));
        o.add(format!("cut_{w}"), ansi::cut(&s, w, w + 7));
    }
    let long = format!("{s} {LONG}");
    for w in [5, 10, 17] {
        o.add(format!("wrap_{w}"), ansi::wrap(&long, w, ""));
        o.add(format!("wordwrap_{w}"), ansi::wordwrap(&long, w, ""));
        o.add(format!("hardwrap_{w}"), ansi::hardwrap(&long, w, true));
        o.add(format!("lipgloss_wrap_{w}"), style::wrap(&long, w, ""));
    }
    o.add("strip", ansi::strip(&s));
    o.add("width", ansi::string_width(&s).to_string());
    let rw: Vec<String> = "a你★→…─│🫧\u{300}\u{200b}".chars().map(|c| ansi::rune_width(c).to_string()).collect();
    o.add("runewidth", rw.join(","));
}

struct Keys {
    short: Vec<Binding>,
    full: Vec<Binding>,
}

impl help::KeyMap for Keys {
    fn short_help(&self) -> Vec<Binding> {
        self.short.clone()
    }
    fn full_help(&self) -> Vec<Vec<Binding>> {
        self.full.chunks(4).map(|c| c.to_vec()).collect()
    }
}

fn help_views(o: &mut Out) {
    let b = |h: &str, d: &str, k: &str| Binding::new().with_keys(&[k]).with_help(h, d);
    let mut dis = b("x", "disabled", "x");
    dis.set_enabled(false);
    let k = Keys {
        short: vec![
            b("tab/l", "next panel", "tab"),
            b("enter", "open", "enter"),
            b("q", "quit", "q"),
            b("?", "all keys", "?"),
            dis,
        ],
        full: vec![
            b("tab/l", "next panel", "tab"),
            b("shift+tab/h", "previous panel", "shift+tab"),
            b("1-6", "a panel", "1"),
            b("[ ]", "its tabs", "["),
            b("0", "the pane", "0"),
            b("enter", "open", "enter"),
            b("esc", "back", "esc"),
            b("q", "quit", "q"),
            b("?", "all keys", "?"),
        ],
    };
    for w in [0, 30, 45, 200] {
        let mut m = help::Model::new();
        m.set_width(w);
        o.add(format!("help_short_{w}"), m.view(&k));
        m.show_all = true;
        o.add(format!("help_full_{w}"), m.view(&k));
    }
}

fn press(k: &str) -> Msg {
    tea::msg(match k {
        "enter" | "esc" | "down" | "up" | "left" | "right" | "backspace" => KeyPressMsg::parse(k),
        _ => KeyPressMsg::char(k.chars().next().unwrap()),
    })
}

