fn new_area() -> textarea::Model {
    let mut q = textarea::Model::new();
    q.prompt = String::new();
    q.show_line_numbers = true;
    q.placeholder = "{ articleList { items { _path } } }".into();
    let mut st = q.styles();
    st.cursor.blink = false;
    for s in [&mut st.focused, &mut st.blurred] {
        s.cursor_line = Style::new();
        s.line_number = S_DIM;
        s.cursor_line_number = S_DIM;
        s.placeholder = S_DIM;
    }
    st.focused.cursor_line_number = S_ACCENT;
    q.set_styles(st);
    q
}

