struct It(&'static str, &'static str);

impl Item for It {
    fn filter_value(&self) -> String {
        self.0.into()
    }
    fn as_default_item(&self) -> Option<&dyn DefaultItem> {
        Some(self)
    }
}

impl DefaultItem for It {
    fn title(&self) -> String {
        self.0.into()
    }
    fn description(&self) -> String {
        self.1.into()
    }
}

fn new_list(singular: &str, plural: &str) -> list::Model {
    let mut d = list::new_default_delegate();
    d.set_spacing(0);
    let mut l = list::Model::new(Vec::new(), d, 0, 0);
    l.set_show_title(false);
    l.set_show_help(false);
    l.set_status_bar_item_name(singular, plural);
    l.disable_quit_keybindings();
    l
}

fn lists(o: &mut Out) {
    let data = [
        ("/apps/site/components/teaser/teaser.html", "file · 18 B"),
        ("/apps/site-packages/application/install/site.ui.config-1.0.zip", "package · 1 KB"),
        ("/conf/site/settings", "folder"),
        ("/content/site/en", "page"),
        ("/content/site/fr", "page"),
    ];
    let mut l = new_list("file", "files");
    l.set_items(data.iter().map(|(t, d)| Box::new(It(t, d)) as Box<dyn Item>).collect());
    l.set_size(40, 12);
    o.add("list_initial", l.view());
    let step = |l: &mut list::Model, k: &str| {
        let cmd: Cmd = l.update(&press(k));
        testing::run(cmd, &mut |m| l.update(&m));
    };
    step(&mut l, "down");
    o.add("list_down", l.view());
    step(&mut l, "/");
    o.add("list_filter_open", l.view());
    for c in "site".chars() {
        step(&mut l, &c.to_string());
    }
    o.add("list_filter_typed", l.view());
    step(&mut l, "enter");
    o.add("list_filter_applied", l.view());
    o.add("list_selected", l.selected_item().unwrap().filter_value());
    step(&mut l, "esc");
    o.add("list_filter_cleared", l.view());
    l.set_size(40, 7);
    o.add("list_small", l.view());
    step(&mut l, "G");
    o.add("list_small_end", l.view());
    let mut empty = new_list("environment", "environments");
    empty.set_size(30, 6);
    o.add("list_empty", empty.view());

    let targets: Vec<String> = data.iter().map(|(t, _)| t.to_string()).collect();
    for pat in ["site", "stc", "cnf", "en", "zzz", "SITE", "a/s"] {
        let parts: Vec<String> = list::fuzzy::find(pat, &targets)
            .iter()
            .map(|m| {
                let idx: Vec<String> = m.matched_indexes.iter().map(i32::to_string).collect();
                format!("{}:{}:[{}]", m.index, m.score, idx.join(" "))
            })
            .collect();
        o.add(format!("fuzzy_{pat}"), parts.join(" "));
    }
}

