fn more(o: &mut Out) {
    // the UI's filter line: fitted to its placeholder, then to what's typed
    let mut i = textinput::Model::new();
    i.prompt = "filter › ".into();
    i.placeholder = "words, or type:page by:admin".into();
    let mut s = i.styles();
    s.cursor.blink = false;
    i.set_styles(s);
    let fit = |i: &mut textinput::Model| {
        let w = if i.value().is_empty() { ansi::string_width(&i.placeholder) } else { 0 };
        i.set_width(w);
    };
    fit(&mut i);
    o.add("fit_blurred", i.view());
    i.focus();
    o.add("fit_focused", i.view());
    for (n, k) in ["t", "y", "p", "e", ":", "p", " ", "b", "y"].iter().enumerate() {
        i.update(&press(k));
        fit(&mut i);
        o.add(format!("fit_typed_{n}"), i.view());
    }
    let edits = [
        KeyPressMsg::with_mods(tea::KEY_BACKSPACE, tea::MOD_ALT),
        KeyPressMsg::with_mods('b' as u32, tea::MOD_ALT),
        KeyPressMsg::with_mods('w' as u32, tea::MOD_CTRL),
        KeyPressMsg::new(tea::KEY_END),
        KeyPressMsg::with_mods('a' as u32, tea::MOD_CTRL),
        KeyPressMsg::with_mods('d' as u32, tea::MOD_ALT),
        KeyPressMsg::with_mods('k' as u32, tea::MOD_CTRL),
    ];
    for (n, k) in edits.into_iter().enumerate() {
        i.update(&tea::msg(k));
        o.add(format!("fit_edit_{n}"), format!("{}|{}|{}", i.value(), i.position(), i.view()));
    }
    i.reset();
    fit(&mut i);
    o.add("fit_reset", i.view());

    // the query editor: typing, a new line, editing across lines
    let mut q = new_area();
    q.set_width(30);
    q.set_height(3);
    q.focus();
    for k in ["{", "enter", "a", "b", "enter", "c", "up", "up", "right"] {
        q.update(&press(k));
        o.add(format!("qa_{k}{} {}", q.line(), q.column()), q.view());
    }
    let edits = [
        KeyPressMsg::with_mods('e' as u32, tea::MOD_CTRL),
        KeyPressMsg::new(tea::KEY_DELETE),
        KeyPressMsg::with_mods('k' as u32, tea::MOD_CTRL),
        KeyPressMsg::with_mods(tea::KEY_BACKSPACE, tea::MOD_ALT),
        KeyPressMsg::with_mods('u' as u32, tea::MOD_CTRL),
        KeyPressMsg::new(tea::KEY_BACKSPACE),
        KeyPressMsg::new(tea::KEY_PGDOWN),
        KeyPressMsg::new(tea::KEY_PGUP),
        KeyPressMsg::with_mods('c' as u32, tea::MOD_ALT),
        KeyPressMsg::with_mods('t' as u32, tea::MOD_CTRL),
    ];
    for (n, k) in edits.into_iter().enumerate() {
        q.update(&tea::msg(k));
        o.add(format!("qa_edit_{n}"), format!("{}|{}:{}|{}", q.value(), q.line(), q.column(), q.view()));
    }
    let mut long = textarea::Model::new();
    long.set_width(20);
    long.set_height(3);
    long.focus();
    long.set_value("one\ntwo\nthree\nfour\nfive\nsix\nseven");
    o.add("ta_long_end", long.view());
    long.update(&tea::msg(KeyPressMsg::new(tea::KEY_PGUP)));
    o.add("ta_long_pgup", format!("{}|{}", long.line(), long.view()));
    long.update(&tea::msg(KeyPressMsg::with_mods('<' as u32, tea::MOD_ALT)));
    o.add("ta_long_begin", format!("{}|{}", long.line(), long.view()));

    // the health tool's viewport: no keys, the wheel
    let mut v = viewport::Model::new();
    v.key_map = viewport::KeyMap::default();
    v.set_width(10);
    v.set_height(3);
    v.set_content("1\n2\n3\n4\n5\n6\n7\n8");
    v.update(&press("down"));
    o.add("vp_nokeys", v.y_offset().to_string());
    v.update(&tea::msg(tea::MouseWheelMsg { button: tea::MouseButton::WheelDown, ..Default::default() }));
    o.add("vp_wheel", format!("{}|{}", v.y_offset(), v.view()));
    v.half_page_down();
    o.add("vp_half", format!("{} {} {}", v.y_offset(), v.at_bottom(), v.scroll_percent()));

    // lists: nothing matches, a long filter, arabic pages, the default list
    let mut l = new_list("package", "packages");
    let names: Vec<(String, String)> =
        (0..30).map(|i| (format!("com.example/package-{i:02}-1.0.zip"), format!("{} KB", i * 3))).collect();
    let leaked: Vec<(&'static str, &'static str)> =
        names.into_iter().map(|(a, b)| (&*Box::leak(a.into_boxed_str()), &*Box::leak(b.into_boxed_str()))).collect();
    l.set_items(leaked.iter().map(|(t, d)| Box::new(It(t, d)) as Box<dyn Item>).collect());
    l.set_size(12, 8);
    o.add("list_arabic", l.view());
    let step = |l: &mut list::Model, k: &str| {
        let cmd: Cmd = l.update(&press(k));
        testing::run(cmd, &mut |m| l.update(&m));
    };
    l.set_size(40, 10);
    step(&mut l, "/");
    for c in "package-1".chars() {
        step(&mut l, &c.to_string());
    }
    o.add("list_long_filter_typing", l.view());
    step(&mut l, "enter");
    o.add("list_long_filter", l.view());
    step(&mut l, "esc");
    step(&mut l, "/");
    for c in "zzz".chars() {
        step(&mut l, &c.to_string());
    }
    o.add("list_nothing", l.view());
    step(&mut l, "enter");
    o.add("list_nothing_enter", format!("{}|{}", l.filter_state().string(), l.view()));

    let def = list::Model::new(
        vec![
            Box::new(It("Raspberry Pi’s", "I have ’em all over my house")),
            Box::new(It("Nutella", "It's good on toast")),
        ],
        list::new_default_delegate(),
        30,
        14,
    );
    o.add("list_default", def.view());

    // more styles
    o.add(
        "bg_padding_width",
        Style::new().background(color("#374151")).foreground(C_TEXT).padding(&[0, 1]).width(14).render("row text"),
    );
    o.add(
        "border_bg",
        Style::new()
            .border(normal_border(), &[])
            .border_background(&[color("1")])
            .border_foreground(&[color("2")])
            .render("x"),
    );
    o.add(
        "border_colors_4",
        Style::new().border(rounded_border(), &[]).border_foreground(&[C_GOOD, C_WARN, C_BAD, C_DIM]).render("four"),
    );
    o.add("margin_padding_border", Style::new().margin(&[1]).padding(&[1]).border(normal_border(), &[]).render("mpb"));
    o.add(
        "inherit",
        Style::new().bold(true).inherit(Style::new().foreground(C_BAD).background(C_DIM).italic(true)).render("in"),
    );
    o.add("place_bottom_right", style::place(8, 3, RIGHT, BOTTOM, "ab\nc"));
    o.add("place_h_partial", style::place_horizontal(9, Position(0.3), "ab\nc"));
    o.add("join_h_bottom_styled", style::join_horizontal(BOTTOM, &[&S_BOX.render("a"), &S_DIM.render("x\ny")]));
    o.add(
        "truncate_styled_tail",
        ansi::truncate(
            &(S_ACCENT.render("› ") + "kind " + &S_ACCENT.bold(true).render("a fairly long entry")),
            15,
            "…",
        ),
    );
}

#[test]
fn renders_as_go() {
    let golden: HashMap<&str, &str> = golden_data::GOLDEN.iter().copied().collect();
    let mut o = Out(Vec::new());
    styles(&mut o);
    ansi_fns(&mut o);
    help_views(&mut o);
    text_inputs(&mut o);
    text_areas(&mut o);
    viewports(&mut o);
    lists(&mut o);
    misc(&mut o);
    more(&mut o);
    let mut failures = Vec::new();
    for (name, got) in &o.0 {
        match golden.get(name.as_str()) {
            Some(want) if *want == got => {}
            Some(want) => failures.push(format!("{name}:\n  go:   {want:?}\n  rust: {got:?}")),
            None => failures.push(format!("{name}: no golden")),
        }
    }
    assert_eq!(o.0.len(), golden_data::GOLDEN.len(), "every golden scenario is rendered");
    assert!(failures.is_empty(), "{} of {} differ:\n{}", failures.len(), o.0.len(), failures.join("\n"));
}
